  'qs.syntax.directives': '列ディレクティブ: `/nn`、`/pk`、`/unique`、`/idx`、`/fk table`、`/check a, b`、`/between 1 and 10`、`/default value`、`/lower`、`/upper`、`[a comment]`。表ディレクティブ: `/auditcols`。',
  'qs.syntax.settings': '設定: `# pk: identity | seq | guid | none`、`# schema: name`、`# prefix: xx`、`# drop: true`、`# auditcols: true`、または `# settings = { pk: "guid", schema: "app" }`。',
  'qs.syntax.views': '`view name table1 table2`: 外部キーで表を結合するビュー。`--` でコメントが始まります。',
