  'rs.facets_help': 'チェックボックスには最も多い値が表示されます(「除外」を使うと逆に除外できます)。範囲と開始/終了には数値または日付の列が必要です。範囲は `from..to = label` を `;` で区切り、開いた端は空にします(`..1000`、`2020-01-01..`)。範囲は開始を含み、終了は含みません。星評価では「星4つ以上」などを選べます(最大5、JSON の `"max"` で変更)。',
