  'rs.calendar_help': 'クエリは `start_date`、`title`、任意で `end_date` を返します(終日イベントは日付、時刻付きイベントはタイムスタンプ)。',
  'rs.chart_help': '最初の列はラベルで、続く数値列がそれぞれ系列になります(最大8)。ガントチャートは `label, start, end`(日付またはタイムスタンプ。終了が空ならマイルストーン)と、任意の列 `progress`(0〜100)、`task_id`、`depends_on`(タスクが待つ id。例: `3,4`)を読み取ります。',
  'rs.map_help': '各行は `lat`、`lng`(または "lat,lng" 形式の `location`)のマーカーで、ポップアップに `title` と `body` が表示されます。`geojson` 列は線と領域を描きます(PostGIS があれば WGS 84 の `geometry` または `geography` 列も使えます)。ヒートマップは各地点を `weight` 列で重み付けします。',
