  'rm.response_as': '{as} として {request}',
  'rm.try_intro': '実際のエンドポイントにリクエストを送信します: PUT、POST、DELETE はデータを変更します。{as}でアカウントを選ぶと、アプリ › REST API と同様に短期間のトークンが発行されます。選ばなければトークンなしの呼出し元が受け取る結果が表示されます。',
  'rm.intro': 'RESTful サービスのモジュール: モジュールはアプリケーションのベース・パスで、テンプレートは `:parameters` 付きの URI です。各テンプレートにはメソッドごとのハンドラとそのソース (コレクション問合せ、単一行、SQL、PL/pgSQL ブロック、メディア・リソース) があります。ハンドラはアプリケーションのデータベース・ロールで実行され、呼出し元は `meta.app_user()` なので、その権限と行レベル・セキュリティが適用されます。パラメータはバインドされ、SQL に貼り付けられることはありません。各モジュールには OpenAPI ドキュメントがあります。モジュールはアプリケーションに属し、エクスポートとともに移動します (共有コンポーネント › RESTful サービスにもあります)。',
  'rm.source_help': 'バインド変数 (大文字): パス・パラメータ ({params})、クエリ・パラメータ、JSON 本文のフィールド。`:BODY` は本文全体、`:APP_USER` は呼出し元です。値はバインドされ、SQL に貼り付けられることはありません。PL/pgSQL: `perform meta.rest_reply(jsonb_build_object(…), 201)` で応答するブロック (`declare … begin … end` または文)。メディア: `content_type`、`content`、任意で `filename` を返す問合せ。',
  'rm.params_help': '1 行に 1 つ: `name query|body|header [{types}] [required] [description]`。OpenAPI ドキュメントと「試す」フォームに使われます。必須のものがなければ 400 を返します。header パラメータは、名前の _ を - に替えたリクエストヘッダーを読みます (`x_request_id` は `X-Request-Id`)。',
  'rm.e.params_line': 'パラメータ、{n} 行目: "name query", "name body" または "name header" と書き、任意で型 ({types})、"required"、説明を続けます。',
